    45→func newEnableCmd() *cobra.Command {
    46→	var localDev bool
    47→	var ignoreUntracked bool
    48→	var useLocalSettings bool
    49→	var useProjectSettings bool
    50→	var agentName string
    51→	var strategyFlag string
    52→	var forceHooks bool
    53→	var skipPushSessions bool
    54→	var telemetry bool
    55→
    56→	cmd := &cobra.Command{
    57→		Use:   "enable",
    58→		Short: "Enable Entire",
    59→		Long: `Enable Entire with session tracking for your AI agent workflows.
    60→
    61→Uses the manual-commit strategy by default. To use a different strategy:
    62→
    63→  entire enable --strategy auto-commit
    64→
    65→Strategies: manual-commit (default), auto-commit`,
    66→		RunE: func(cmd *cobra.Command, _ []string) error {
    67→			// Check if we're in a git repository first - this is a prerequisite error,
    68→			// not a usage error, so we silence Cobra's output and use SilentError
    69→			// to prevent duplicate error output in main.go
    70→			if _, err := paths.RepoRoot(); err != nil {
    71→				cmd.SilenceUsage = true
    72→				cmd.SilenceErrors = true
    73→				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run 'entire enable' from within a git repository.")
    74→				return NewSilentError(errors.New("not a git repository"))
    75→			}
    76→
    77→			if err := validateSetupFlags(useLocalSettings, useProjectSettings); err != nil {
    78→				return err
    79→			}
    80→			// Non-interactive mode if --agent flag is provided
    81→			if agentName != "" {
    82→				return setupAgentHooksNonInteractive(cmd.OutOrStdout(), agent.AgentName(agentName), strategyFlag, localDev, forceHooks, skipPushSessions, telemetry)
    83→			}
    84→			// If strategy is specified via flag, skip interactive selection
    85→			if strategyFlag != "" {
    86→				return runEnableWithStrategy(cmd.OutOrStdout(), strategyFlag, localDev, ignoreUntracked, useLocalSettings, useProjectSettings, forceHooks, skipPushSessions, telemetry)
    87→			}
    88→			return runEnableInteractive(cmd.OutOrStdout(), localDev, ignoreUntracked, useLocalSettings, useProjectSettings, forceHooks, skipPushSessions, telemetry)
    89→		},
    90→	}
