   145→// isFullyEnabled checks whether Entire is already fully set up.
   146→// Returns whether it's fully enabled, and if so, the agent type display name and config file path.
   147→func isFullyEnabled() (enabled bool, agentDesc string, configPath string) {
   148→	// Check settings exist and Enabled == true
   149→	s, err := LoadEntireSettings()
   150→	if err != nil || !s.Enabled {
   151→		return false, "", ""
   152→	}
   153→
   154→	// Check any agent hooks installed (not just Claude Code — works with Gemini too)
   155→	installedAgents := GetAgentsWithHooksInstalled()
   156→	if len(installedAgents) == 0 {
   157→		return false, "", ""
   158→	}
   159→
   160→	// Check git hooks installed
   161→	if !strategy.IsGitHookInstalled() {
   162→		return false, "", ""
   163→	}
   164→
   165→	// Check .entire directory exists
   166→	if !checkEntireDirExists() {
   167→		return false, "", ""
   168→	}
   169→
   170→	// Determine agent description from first installed agent
   171→	desc := string(installedAgents[0]) // fallback to agent name
   172→	if ag, err := agent.Get(installedAgents[0]); err == nil {
   173→		desc = string(ag.Type())
   174→	}
   175→
   176→	// Determine config path - check if local settings exists, otherwise show project settings
   177→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   178→	if err != nil {
   179→		entireDirAbs = paths.EntireDir
   180→	}
   181→	configDisplay := configDisplayProject
   182→	localSettingsPath := filepath.Join(entireDirAbs, "settings.local.json")
   183→	if _, err := os.Stat(localSettingsPath); err == nil {
   184→		configDisplay = configDisplayLocal
   185→	}
   186→
   187→	return true, desc, configDisplay
   188→}
