   190→// runEnableWithStrategy enables Entire with a specified strategy (non-interactive).
   191→// The selectedStrategy can be either a display name (manual-commit, auto-commit)
   192→// or an internal name (manual-commit, auto-commit).
   193→func runEnableWithStrategy(w io.Writer, selectedStrategy string, localDev, _, useLocalSettings, useProjectSettings, forceHooks, skipPushSessions, telemetry bool) error {
   194→	// Map the strategy to internal name if it's a display name
   195→	internalStrategy := selectedStrategy
   196→	if mapped, ok := strategyDisplayToInternal[selectedStrategy]; ok {
   197→		internalStrategy = mapped
   198→	}
   199→
   200→	// Validate the strategy exists
   201→	strat, err := strategy.Get(internalStrategy)
   202→	if err != nil {
   203→		return fmt.Errorf("unknown strategy: %s (use manual-commit or auto-commit)", selectedStrategy)
   204→	}
   205→
   206→	// Detect default agent
   207→	ag := agent.Default()
   208→	agentType := string(agent.AgentTypeClaudeCode)
   209→	if ag != nil {
   210→		agentType = string(ag.Type())
   211→	}
   212→	fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", agentType)
   213→
   214→	// Setup Claude Code hooks + git hooks → combined "Hooks installed" message
   215→	if _, err := setupClaudeCodeHook(localDev, forceHooks); err != nil {
   216→		return fmt.Errorf("failed to setup Claude Code hooks: %w", err)
   217→	}
   218→	if _, err := strategy.InstallGitHook(true); err != nil {
   219→		return fmt.Errorf("failed to install git hooks: %w", err)
   220→	}
   221→	fmt.Fprintln(w, "✓ Hooks installed")
   222→
   223→	// Setup .entire directory
   224→	if _, err := setupEntireDirectory(); err != nil {
   225→		return fmt.Errorf("failed to setup .entire directory: %w", err)
   226→	}
   227→
   228→	// Load existing settings to preserve other options (like strategy_options.push)
   229→	settings, err := LoadEntireSettings()
   230→	if err != nil {
   231→		// If we can't load, start with defaults
   232→		settings = &EntireSettings{}
   233→	}
   234→	// Update the specific fields
   235→	settings.Strategy = internalStrategy
   236→	settings.LocalDev = localDev
   237→	settings.Enabled = true
   238→
   239→	// Set push_sessions option if --skip-push-sessions flag was provided
   240→	if skipPushSessions {
   241→		if settings.StrategyOptions == nil {
   242→			settings.StrategyOptions = make(map[string]interface{})
   243→		}
   244→		settings.StrategyOptions["push_sessions"] = false
   245→	}
   246→
   247→	// Handle telemetry for non-interactive mode
   248→	// Note: if telemetry is nil (not configured), it defaults to disabled
   249→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   250→		f := false
   251→		settings.Telemetry = &f
   252→	}
   253→
   254→	// Determine which settings file to write to
   255→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   256→	if err != nil {
   257→		entireDirAbs = paths.EntireDir // Fallback to relative
   258→	}
   259→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
   260→
   261→	if showNotification {
   262→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
   263→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
   264→	}
   265→
   266→	configDisplay := configDisplayProject
   267→	if shouldUseLocal {
   268→		if err := SaveEntireSettingsLocal(settings); err != nil {
   269→			return fmt.Errorf("failed to save local settings: %w", err)
   270→		}
   271→		configDisplay = configDisplayLocal
   272→	} else {
   273→		if err := SaveEntireSettings(settings); err != nil {
   274→			return fmt.Errorf("failed to save settings: %w", err)
   275→		}
   276→	}
   277→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
   278→
   279→	// Let the strategy handle its own setup requirements
   280→	if err := strat.EnsureSetup(); err != nil {
   281→		return fmt.Errorf("failed to setup strategy: %w", err)
   282→	}
   283→
   284→	fmt.Fprintln(w, "\nReady.")
   285→
   286→	return nil
   287→}
