   289→// runEnableInteractive runs the interactive enable flow.
   290→func runEnableInteractive(w io.Writer, localDev, _, useLocalSettings, useProjectSettings, forceHooks, skipPushSessions, telemetry bool) error {
   291→	// Check if already fully enabled — show summary and return early.
   292→	// Skip early return if any configuration flags are set (user wants to reconfigure).
   293→	hasConfigFlags := forceHooks || skipPushSessions || !telemetry || useLocalSettings || useProjectSettings || localDev
   294→	if !hasConfigFlags {
   295→		if fullyEnabled, agentDesc, configPath := isFullyEnabled(); fullyEnabled {
   296→			fmt.Fprintln(w, "Already enabled. Everything looks good.")
   297→			fmt.Fprintln(w)
   298→			fmt.Fprintf(w, "  Agent: %s\n", agentDesc)
   299→			fmt.Fprintf(w, "  Config: %s\n", configPath)
   300→			return nil
   301→		}
   302→	}
   303→
   304→	// Detect default agent
   305→	ag := agent.Default()
   306→	agentType := string(agent.AgentTypeClaudeCode)
   307→	if ag != nil {
   308→		agentType = string(ag.Type())
   309→	}
   310→	fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", agentType)
   311→
   312→	// Install Claude Code hooks + git hooks → combined "Hooks installed" message
   313→	if _, err := setupClaudeCodeHook(localDev, forceHooks); err != nil {
   314→		return fmt.Errorf("failed to setup Claude Code hooks: %w", err)
   315→	}
   316→	if _, err := strategy.InstallGitHook(true); err != nil {
   317→		return fmt.Errorf("failed to install git hooks: %w", err)
   318→	}
   319→	fmt.Fprintln(w, "✓ Hooks installed")
   320→
   321→	// Setup .entire directory
   322→	if _, err := setupEntireDirectory(); err != nil {
   323→		return fmt.Errorf("failed to setup .entire directory: %w", err)
   324→	}
   325→
   326→	// Use the default strategy (manual-commit)
   327→	internalStrategy := strategy.DefaultStrategyName
   328→
   329→	// Load existing settings to preserve other options (like strategy_options.push)
   330→	settings, err := LoadEntireSettings()
   331→	if err != nil {
   332→		// If we can't load, start with defaults
   333→		settings = &EntireSettings{}
   334→	}
   335→	// Update the specific fields
   336→	settings.Strategy = internalStrategy
   337→	settings.LocalDev = localDev
   338→	settings.Enabled = true
   339→
   340→	// Set push_sessions option if --skip-push-sessions flag was provided
   341→	if skipPushSessions {
   342→		if settings.StrategyOptions == nil {
   343→			settings.StrategyOptions = make(map[string]interface{})
   344→		}
   345→		settings.StrategyOptions["push_sessions"] = false
   346→	}
   347→
   348→	// Determine which settings file to write to
   349→	// First run always creates settings.json (no prompt)
   350→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   351→	if err != nil {
   352→		entireDirAbs = paths.EntireDir // Fallback to relative
   353→	}
   354→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
   355→
   356→	if showNotification {
   357→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
   358→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
   359→	}
   360→
   361→	// Helper to save settings to the appropriate file
   362→	saveSettings := func() error {
   363→		if shouldUseLocal {
   364→			return SaveEntireSettingsLocal(settings)
   365→		}
   366→		return SaveEntireSettings(settings)
   367→	}
   368→
   369→	// Save settings before telemetry prompt so config is persisted even if the user cancels
   370→	if err := saveSettings(); err != nil {
   371→		return fmt.Errorf("failed to save settings: %w", err)
   372→	}
   373→	configDisplay := configDisplayProject
   374→	if shouldUseLocal {
   375→		configDisplay = configDisplayLocal
   376→	}
   377→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
   378→
   379→	// Ask about telemetry consent (only if not already asked)
   380→	fmt.Fprintln(w)
   381→	if err := promptTelemetryConsent(settings, telemetry); err != nil {
   382→		return fmt.Errorf("telemetry consent: %w", err)
   383→	}
   384→	// Save again to persist telemetry choice
   385→	if err := saveSettings(); err != nil {
   386→		return fmt.Errorf("failed to save settings: %w", err)
   387→	}
   388→
   389→	// Let the strategy handle its own setup requirements
   390→	strat, err := strategy.Get(internalStrategy)
   391→	if err != nil {
   392→		return fmt.Errorf("failed to get strategy: %w", err)
   393→	}
   394→	if err := strat.EnsureSetup(); err != nil {
   395→		return fmt.Errorf("failed to setup strategy: %w", err)
   396→	}
   397→
   398→	fmt.Fprintln(w, "\nReady.")
   399→
   400→	return nil
   401→}
