   403→// runEnable is a simple enable that just sets the enabled flag (for programmatic use).
   404→func runEnable(w io.Writer) error {
   405→	settings, err := LoadEntireSettings()
   406→	if err != nil {
   407→		return fmt.Errorf("failed to load settings: %w", err)
   408→	}
