   419→func runDisable(w io.Writer, useProjectSettings bool) error {
   420→	settings, err := LoadEntireSettings()
   421→	if err != nil {
   422→		return fmt.Errorf("failed to load settings: %w", err)
   423→	}
   424→
   425→	settings.Enabled = false
   426→
   427→	// If --project flag is specified, always write to project settings
   428→	if useProjectSettings {
   429→		if err := SaveEntireSettings(settings); err != nil {
   430→			return fmt.Errorf("failed to save settings: %w", err)
   431→		}
   432→	} else {
   433→		// Always write to local settings file (create if doesn't exist)
   434→		if err := SaveEntireSettingsLocal(settings); err != nil {
   435→			return fmt.Errorf("failed to save local settings: %w", err)
   436→		}
   437→	}
   438→
   439→	fmt.Fprintln(w, "Entire is now disabled.")
   440→	return nil
   441→}
