   443→// DisabledMessage is the message shown when Entire is disabled
   444→const DisabledMessage = "Entire is disabled. Run `entire enable` to re-enable."
   445→
   446→// checkDisabledGuard checks if Entire is disabled and prints a message if so.
   447→// Returns true if the caller should exit (i.e., Entire is disabled).
   448→// On error reading settings, defaults to enabled (returns false).
   449→func checkDisabledGuard(w io.Writer) bool {
   450→	enabled, err := IsEnabled()
   451→	if err != nil {
   452→		// Default to enabled on error
   453→		return false
   454→	}
   455→	if !enabled {
   456→		fmt.Fprintln(w, DisabledMessage)
   457→		return true
   458→	}
   459→	return false
   460→}
