   462→// setupClaudeCodeHook sets up Claude Code hooks.
   463→// This is a convenience wrapper that uses the agent package.
   464→// Returns the number of hooks installed (0 if already installed).
   465→func setupClaudeCodeHook(localDev, forceHooks bool) (int, error) {
   466→	ag, err := agent.Get(agent.AgentNameClaudeCode)
   467→	if err != nil {
   468→		return 0, fmt.Errorf("failed to get claude-code agent: %w", err)
   469→	}
   470→
   471→	hookAgent, ok := ag.(agent.HookSupport)
   472→	if !ok {
   473→		return 0, errors.New("claude-code agent does not support hooks")
   474→	}
   475→
   476→	count, err := hookAgent.InstallHooks(localDev, forceHooks)
   477→	if err != nil {
   478→		return 0, fmt.Errorf("failed to install claude-code hooks: %w", err)
   479→	}
   480→
   481→	return count, nil
   482→}
