   484→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
   485→// If strategyName is provided, it sets the strategy; otherwise uses default.
   486→func setupAgentHooksNonInteractive(w io.Writer, agentName agent.AgentName, strategyName string, localDev, forceHooks, skipPushSessions, telemetry bool) error {
   487→	ag, err := agent.Get(agentName)
   488→	if err != nil {
   489→		return fmt.Errorf("unknown agent: %s", agentName)
   490→	}
   491→
   492→	// Check if agent supports hooks
   493→	hookAgent, ok := ag.(agent.HookSupport)
   494→	if !ok {
   495→		return fmt.Errorf("agent %s does not support hooks", agentName)
   496→	}
   497→
   498→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
   499→
   500→	// Install agent hooks + git hooks
   501→	if _, err := hookAgent.InstallHooks(localDev, forceHooks); err != nil {
   502→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
   503→	}
   504→	if _, err := strategy.InstallGitHook(true); err != nil {
   505→		return fmt.Errorf("failed to install git hooks: %w", err)
   506→	}
   507→
   508→	if agentName == agent.AgentNameGemini {
   509→		fmt.Fprintln(w, "✓ Hooks installed - This is a work in progress")
   510→	} else {
   511→		fmt.Fprintln(w, "✓ Hooks installed")
   512→	}
   513→
   514→	// Setup .entire directory
   515→	if _, err := setupEntireDirectory(); err != nil {
   516→		return fmt.Errorf("failed to setup .entire directory: %w", err)
   517→	}
   518→
   519→	// Update settings to store the strategy
   520→	settings, _ := LoadEntireSettings() //nolint:errcheck // settings defaults are fine
   521→	settings.Enabled = true
   522→	if localDev {
   523→		settings.LocalDev = localDev
   524→	}
   525→
   526→	// Set push_sessions option if --skip-push-sessions flag was provided
   527→	if skipPushSessions {
   528→		if settings.StrategyOptions == nil {
   529→			settings.StrategyOptions = make(map[string]interface{})
   530→		}
   531→		settings.StrategyOptions["push_sessions"] = false
   532→	}
   533→
   534→	// Set strategy if provided
   535→	if strategyName != "" {
   536→		// Map display name to internal name if needed
   537→		internalStrategy := strategyName
   538→		if mapped, ok := strategyDisplayToInternal[strategyName]; ok {
   539→			internalStrategy = mapped
   540→		}
   541→		// Validate the strategy exists
   542→		if _, err := strategy.Get(internalStrategy); err != nil {
   543→			return fmt.Errorf("unknown strategy: %s (use manual-commit or auto-commit)", strategyName)
   544→		}
   545→		settings.Strategy = internalStrategy
   546→	}
   547→
   548→	// Handle telemetry for non-interactive mode
   549→	// Note: if telemetry is nil (not configured), it defaults to disabled
   550→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
