   558→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
   559→
   560→	// Let the strategy handle its own setup requirements (creates entire/sessions branch, etc.)
   561→	strat, err := strategy.Get(settings.Strategy)
