   830→// runUninstall completely removes Entire from the repository.
   831→func runUninstall(w, errW io.Writer, force bool) error {
   832→	// Check if we're in a git repository
   833→	if _, err := paths.RepoRoot(); err != nil {
   834→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
   835→		return NewSilentError(errors.New("not a git repository"))
   836→	}
   837→
   838→	// Gather counts for display
   839→	sessionStateCount := countSessionStates()
   840→	shadowBranchCount := countShadowBranches()
   841→	gitHooksInstalled := strategy.IsGitHookInstalled()
   842→	claudeHooksInstalled := checkClaudeCodeHooksInstalled()
   843→	geminiHooksInstalled := checkGeminiCLIHooksInstalled()
   844→	entireDirExists := checkEntireDirExists()
   845→
   846→	// Check if there's anything to uninstall
   847→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
   848→		shadowBranchCount == 0 && !claudeHooksInstalled && !geminiHooksInstalled {
   849→		fmt.Fprintln(w, "Entire is not installed in this repository.")
   850→		return nil
   851→	}
   852→
   853→	// Show confirmation prompt unless --force
   854→	if !force {
   855→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
   856→		if entireDirExists {
   857→			fmt.Fprintln(w, "  - .entire/ directory")
   858→		}
   859→		if gitHooksInstalled {
   860→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
   861→		}
   862→		if sessionStateCount > 0 {
   863→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
   864→		}
   865→		if shadowBranchCount > 0 {
   866→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
   867→		}
   868→		switch {
   869→		case claudeHooksInstalled && geminiHooksInstalled:
   870→			fmt.Fprintln(w, "  - Agent hooks (Claude Code, Gemini CLI)")
   871→		case claudeHooksInstalled:
   872→			fmt.Fprintln(w, "  - Agent hooks (Claude Code)")
   873→		case geminiHooksInstalled:
   874→			fmt.Fprintln(w, "  - Agent hooks (Gemini CLI)")
   875→		}
   876→		fmt.Fprintln(w)
   877→
   878→		var confirmed bool
   879→		form := NewAccessibleForm(
   880→			huh.NewGroup(
   881→				huh.NewConfirm().
   882→					Title("Are you sure you want to uninstall Entire?").
   883→					Affirmative("Yes, uninstall").
   884→					Negative("Cancel").
   885→					Value(&confirmed),
   886→			),
   887→		)
   888→
   889→		if err := form.Run(); err != nil {
   890→			return fmt.Errorf("confirmation cancelled: %w", err)
   891→		}
   892→
   893→		if !confirmed {
   894→			fmt.Fprintln(w, "Uninstall cancelled.")
   895→			return nil
   896→		}
   897→	}
   898→
   899→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
   900→
   901→	// 1. Remove agent hooks (lowest risk)
   902→	if err := removeAgentHooks(w); err != nil {
   903→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
   904→	}
   905→
   906→	// 2. Remove git hooks
   907→	removed, err := strategy.RemoveGitHook()
   908→	if err != nil {
   909→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
   910→	} else if removed > 0 {
   911→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
   912→	}
   913→
   914→	// 3. Remove session state files
   915→	statesRemoved, err := removeAllSessionStates()
   916→	if err != nil {
   917→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
   918→	} else if statesRemoved > 0 {
   919→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
   920→	}
   921→
   922→	// 4. Remove .entire/ directory
   923→	if err := removeEntireDirectory(); err != nil {
   924→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
   925→	} else if entireDirExists {
   926→		fmt.Fprintln(w, "  Removed .entire directory")
   927→	}
   928→
   929→	// 5. Remove shadow branches
   930→	branchesRemoved, err := removeAllShadowBranches()
   931→	if err != nil {
   932→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
   933→	} else if branchesRemoved > 0 {
   934→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
   935→	}
   936→
   937→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
   938→	return nil
   939→}
